
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_lrc_wpbeh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_lrc_wpbeh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.416829396009554e+00, -3.350416628708264e+00, -3.257410586196404e+00, -3.128689520371885e+00, -2.953538070651970e+00, -2.720958482747882e+00, -2.422754768205978e+00, -2.059051738795779e+00, -1.645392852544511e+00, -1.213487727011737e+00, -7.909895711298597e-01, -5.177684896625501e-01, -4.421414392206088e-01, -3.467044589826552e-01, -2.262722873794174e-01, -1.147795358912973e-01, -3.515156476084896e-02, -1.589890480631643e-03, -8.688278933389953e-06, -1.192235376413397e-08]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


